/** @file a.h
 *  @brief A file about classes.
 */

/// A base class.
class Base {
public:
  /// pub method
  virtual void pub();
protected:
  int prot_;   ///< protected member
private:
  int priv_;   //!< private member
};

/*! Another base */
struct Base2 { int x; };

/** Derived from Base publicly and Base2 privately. */
class Derived : public virtual Base, private Base2 {
public:
  /** Nested class. */
  class Inner {
  public:
    int i; ///< inner field
  };
  /** nested struct */
  struct InnerS { double d; };
  /** nested enum */
  enum Color { RED, GREEN=5, BLUE };
  /** enum class */
  enum class Scoped : unsigned char { A, B };
  void pub() override;
  int f(int a, const char *b = "hi", double c = 3.5) const noexcept;
  static int s_count;
  static void sfun();
  inline int inl() { return 1; }
  explicit Derived(int);
  virtual ~Derived() = default;
  virtual void pure() = 0;
  int (*fp)(int, char);            ///< function pointer member
  void takesFp(int (*cb)(void*), void *ud);
  union U { int i; float f; };
};

/** a union */
union FreeUnion { int i; char c[4]; };

/** template class @tparam T the type @tparam N count */
template<typename T, int N = 3>
class TC {
public:
  T data[N];
  /** template method @tparam U u type */
  template<class U> U conv(T t);
};

/** partial spec */
template<typename T> class TC<T,1> { public: T only; };
EOF
